 /* Miscellaneous Mixins */
 .settings-panel .chat-list .list .info p, .email-wrapper .message-body .attachments-sections ul li .details p.file-name, .email-wrapper .mail-list-container .mail-list .content .sender-name, .email-wrapper .mail-sidebar .menu-bar .profile-list-item a .user .u-designation, .email-wrapper .mail-sidebar .menu-bar .profile-list-item a .user .u-name, .list-wrapper ul li .form-check .form-check-label, .list-wrapper ul li .form-check {
