 .settings-panel {
   display: block;
   position: fixed;
   top: 0;
   right: -300px;
   bottom: 0;
   width: 300px;
   height: 100vh;
   min-height: 100%;
   background: #ffffff;
   -webkit-transition-duration: 0.25s;
