.count-indicator {
  position: relative;

  .count-symbol,
  .count-number {
    position: absolute;
    border-radius: 100%;
    border: 2px solid $white;

    animation: pulse 3s ease-out;
    animation-iteration-count: infinite;
  }

  @keyframes pulse {
    40% {
      transform: scale3d(1, 1, 1);
    }

    50% {
      transform: scale3d(1.5, 1.5, 1.5);
    }

    55% {
      transform: scale3d(1, 1, 1);
    }

    60% {
      transform: scale3d(1.5, 1.5, 1.5);
    }

    65% {
      transform: scale3d(1, 1, 1);
    }
  }
  .count-symbol {
    top: 20px;
    right: 0px;
    width: 10px;
    height: 10px;
  }
  .count-number {
    min-width: 14px;
    height: 14px;
    font-size: .5rem;
    color: $white;
    bottom: 16px;
    right: -5px;
    line-height: 1;
    text-align: center;
  }
