            position: relative;
            border-bottom: none;
            .menu-title {
              display: block;
              margin: auto;
            }
            .menu-sub-title{
              margin: auto;
            }
            .badge {
              margin-left: 5px;
              display: none;
            }
            .icon-bg {
              margin-top: 8px;
              i {
                &.menu-icon {
                  display:block;
                  margin-right: auto;
                  margin-left: auto;
                  margin-top: 5px;
                }

              }
            }
            i {

            &.menu-arrow {
              display: inline-block;
              margin-left: 5px;
              position: absolute;
              top: 50%;
              right: 10px;
              @include transform(translateY(-50%));
              &:before {
                content: "\F0140";
              }
            }

            }

            &[aria-expanded="true"]{
              .menu-arrow{
                &:before{
                  content: "\F0143";
                }
              }
            }
          }
          &.nav-category {
            text-align:center;
          }
          &.sidebar-user-actions {
            .sidebar-profile-text {
              display: none;
            } 
            &.hover-open {
              .nav-link {
                .menu-title {
                  left: 45px;
                }
              }
            }

          }
        }
      }
    }

    .main-panel {
      width: calc(100% - #{$sidebar-width-mini});
    }
    &:not(.sidebar-icon-only) {
      //Apply these styles only when sidebar-mini is not collapsed to icon-only mode
      .sidebar {
        .nav {
          &:not(.sub-menu) {
            > .nav-item {
              border-bottom: 1px solid rgba($sidebar-light-menu-color, .2);
              .nav-link {
                height: auto;
                padding: $sidebar-mini-menu-padding;
                i {
                  &.menu-icon {
                    margin-bottom: .5rem;
                  }
                }
              }
            }
          }
          &.sub-menu {
            padding: 0;
            border-top: none;
            .nav-item {
              padding: 5px 0;
              .nav-link {
                padding: 7px 0 7px 25px;
                margin-left: auto;
                margin-right: auto;
                display: block;
                text-align: left;
                width: 66%;
              }
            }
          }
        }
      }
    }
  }
