display.text:
/* Shared spacing and responsive layout, loaded after the template styles. */
:root {
  --app-font: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Arial, sans-serif;
  --app-gutter: clamp(1rem, 2.5vw, 2.5rem);
}
body { line-height: 1.5; }
.font-weight-light { font-weight: 300; }
.font-weight-normal { font-weight: 400; }
.font-weight-medium { font-weight: 600; }
.font-weight-bold { font-weight: 700; }
button, input, select, textarea { font-family: inherit; }
.main-panel, .content-wrapper, .row > *, .card, .card-body { min-width: 0; }
.sidebar { flex-shrink: 0; }
.content-wrapper { padding: var(--app-gutter) var(--app-gutter) 0; }
.page-header { margin-inline: 0; flex-wrap: wrap; gap: 1rem; }
.page-header .breadcrumb { flex-wrap: wrap; }
.card .card-body { padding: 1.5rem; }
.grid-margin { margin-bottom: 1.5rem; }
.tab-content { text-align: start; }
.footer { padding: 1.5rem var(--app-gutter); line-height: 1.6; }
.footer .footer-inner-wraper { padding: 0; }
.footer-inner-wraper > div { gap: .75rem; flex-wrap: wrap; }
.navbar .navbar-menu-wrapper { min-width: 0; flex: 1; }
.navbar .navbar-menu-wrapper .navbar-nav.navbar-nav-right { margin-left: auto; }
.navbar .search-field { min-width: 0; flex: 1; }
.navbar .navbar-menu-wrapper .search-field .input-group { width: 100%; max-width: 305px; flex-wrap: nowrap; }
.navbar .input-group-prepend { display: flex; align-items: center; }
.navbar .navbar-menu-wrapper .navbar-nav .nav-item .nav-link { margin-inline: .5rem; }
.navbar .navbar-menu-wrapper .navbar-nav .nav-item.nav-profile .nav-link .nav-profile-img { flex-shrink: 0; }
.dashboard-heading { display: flex; flex-wrap: wrap; gap: 1rem; margin-bottom: 1.5rem; }
.dashboard-filters { display: flex; flex-wrap: wrap; gap: .75rem; }
.dashboard-filters .btn-group { padding: .75rem .25rem !important; }
.dashboard-filters .dropdown { margin: 0 !important; }
.dashboard-filters .btn { min-height: 44px; white-space: nowrap; }
.dashboard-tabs { min-width: 0; }
.dashboard-tabs .nav-tabs { flex-wrap: nowrap; overflow-x: auto; min-width: 0; max-width: 100%; }
.dashboard-tabs .nav-item { flex-shrink: 0; }
.dashboard-tabs .nav-link { min-height: 44px; }
.dashboard-stats .card-body { display: flex; flex-direction: column; align-items: center; }
.dashboard-stats .card-body > p { min-height: 3em; display: flex; align-items: center; }
.dashboard-stats .card-body > h3 { margin-top: auto !important; }
.retention-summary { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.25rem; }
.retention-summary > div { width: auto; padding: 0; }
.retention-summary h4 { font-size: .875rem; }
.retention-summary h1 { font-size: clamp(1.25rem, 2vw, 1.875rem); }
.graph-custom-legend ul { flex-wrap: wrap; gap: .5rem 1rem; padding: 0; float: none !important; }
#page-view-analytic-legend ul li { margin-left: 0; }
.table-responsive { max-width: 100%; -webkit-overflow-scrolling: touch; }
.content-wrapper canvas { max-width: 100%; }
.btn:focus-visible, a:focus-visible, .navbar-toggler:focus-visible { outline: 2px solid #6263ef; outline-offset: 3px; }
/* Keep the promotion in normal flow so its wrapped height cannot cover navigation. */
#proBanner { position: relative; height: auto; }
#proBanner .card-body-padding { gap: .75rem; padding: .5rem var(--app-gutter); }
#proBanner .buy-now-btn, #proBanner .card-body-padding > div:last-child { flex-shrink: 0; }
#proBanner #bannerClose { min-width: 44px; min-height: 44px; }
.navbar.proBanner-padding-top { padding-top: 0 !important; }
@media (min-width: 992px) and (max-width: 1199.98px) {
  .navbar .navbar-menu-wrapper { padding-inline: 1rem; }
  .navbar .nav-profile-text { display: none; }
}
@media (max-width: 991.98px) {
  .navbar .navbar-menu-wrapper { padding-inline: .5rem; }
  .navbar .navbar-menu-wrapper .navbar-toggler.navbar-toggler-right { padding-inline: .75rem; min-width: 44px; }
  .sidebar-offcanvas { max-width: calc(100vw - 48px); top: var(--app-nav-bottom, 64px); max-height: calc(100dvh - var(--app-nav-bottom, 64px)); visibility: hidden; }
  .sidebar-offcanvas.active { visibility: visible; box-shadow: -8px 12px 24px #18234426; }
  .navbar .navbar-menu-wrapper .navbar-nav .nav-item.dropdown .navbar-dropdown { max-height: calc(100dvh - 90px); overflow-y: auto; }
}
@media (max-width: 575.98px) {
  .navbar .navbar-brand-wrapper { width: 55px; flex-shrink: 0; }
  .navbar .navbar-menu-wrapper .navbar-nav .nav-item .nav-link { margin-inline: .125rem; padding-inline: .5rem; min-width: 44px; justify-content: center; }
  .dashboard-heading h2 { font-size: 1.375rem; }
  .dashboard-filters, .dashboard-filters > *, .dashboard-filters .dropdown > button { width: 100%; }
  .dashboard-filters .dropdown > button { justify-content: center; }
  .dashboard-filters .btn-group .btn { flex: 1; padding-inline: .5rem; }
  .dashboard-tabs .nav-tabs.tab-transparent .nav-link { padding-inline: 1rem; }
  .card .card-body { padding: 1.25rem; }
  .auth .auth-form-light, .auth .auth-form-dark { padding: 1.5rem !important; }
  .auth form .d-flex { flex-wrap: wrap; gap: .75rem; }
  .form-control, .form-select { font-size: 1rem; }
  #proBanner .card-body-padding > div:first-child { flex: 1; }
  #proBanner .card-body-padding > div:first-child > div { flex-wrap: wrap; }
  #proBanner .buy-now-text { font-size: .75rem; }
  #proBanner .btn.buy-now-btn { min-width: 0; padding: .5rem 0; }
  #proBanner .card-body-padding > div:last-child > a { display: none; }
}

