input.command:
node -e '
const fs = require("fs");
const root = "connect-plus-free";
const font = "\"Segoe UI\", system-ui, -apple-system, BlinkMacSystemFont, Arial, sans-serif";
const responsive = fs.readFileSync(`${root}/src/assets/scss/shared/_responsive.scss`, "utf8");

for (const tree of ["src", "dist"]) {
  const base = `${root}/${tree}`;
  const cssFile = `${base}/assets/css/vertical-light-layout/style.css`;
  let css = fs.readFileSync(cssFile, "utf8");
  css = css.replace(/(["\x27])nunito-(?:light|regular|medium|bold)\1,\s*sans-serif/g, font);
  if (!css.includes("/* Shared spacing and responsive layout")) {
    css = css + "\n" + responsive;
  }
  fs.writeFileSync(cssFile, css);

  const htmlFile = `${base}/index.html`;
  let html = fs.readFileSync(htmlFile, "utf8");
  html = html
    .replaceAll("../../../assets/images/", "assets/images/")
    .replace("class=\"d-xl-flex justify-content-between align-items-start\"", "class=\"dashboard-heading justify-content-between align-items-center\"")
    .replace("class=\"d-sm-flex justify-content-xl-between align-items-center mb-2\"", "class=\"dashboard-filters align-items-center\"")
    .replace("transaparent-tab-border {", "transaparent-tab-border dashboard-tabs")
    .replace(/<div class="row">(\r?\n\s+<div class="col-xl-3)/, "<div class=\"row dashboard-stats\">$1")
    .replace("col-sm-4 grid-margin stretch-card", "col-12 col-xl-5 grid-margin stretch-card")
    .replace("col-sm-8  grid-margin stretch-card", "col-12 col-xl-7 grid-margin stretch-card")
    .replace("row pt-4", "retention-summary")
    .replace("id=\"bannerClose\"", "id=\"bannerClose\" aria-label=\"Dismiss promotion\"");
  fs.writeFileSync(htmlFile, html);
}
console.log("Updated CSS and HTML successfully!");
'

